describe('Background Sync Toast Notification', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const toastSelector = '[data-testid="toast-notification"]';
  const syncButtonSelector = '[data-testid="sync-button"]';
  const toastMessageSelector = '[data-testid="toast-message"]';
  const toastCloseSelector = '[data-testid="toast-close"]';

  beforeEach(() => {
    cy.visit(baseUrl);
    cy.intercept('POST', '**/api/sync', {
      statusCode: 200,
      body: { success: true, message: 'Sync completed successfully' },
      delay: 500
    }).as('backgroundSync');
  });

  it('should display toast notification when background sync completes successfully', () => {
    cy.get(syncButtonSelector).should('be.visible').click();

    cy.wait('@backgroundSync');

    cy.get(toastSelector)
      .should('be.visible')
      .and('have.class', 'toast-success');

    cy.get(toastMessageSelector)
      .should('contain.text', 'Sync completed successfully');

    cy.get(toastSelector).should('have.attr', 'role', 'alert');
  });

  it('should auto-dismiss toast notification after 5 seconds', () => {
    cy.get(syncButtonSelector).click();

    cy.wait('@backgroundSync');

    cy.get(toastSelector).should('be.visible');

    cy.get(toastSelector).should('not.exist', { timeout: 6000 });
  });

  it('should display error toast when background sync fails', () => {
    cy.intercept('POST', '**/api/sync', {
      statusCode: 500,
      body: { success: false, message: 'Sync failed: Server error' }
    }).as('backgroundSyncError');

    cy.get(syncButtonSelector).click();

    cy.wait('@backgroundSyncError');

    cy.get(toastSelector)
      .should('be.visible')
      .and('have.class', 'toast-error');

    cy.get(toastMessageSelector)
      .should('contain.text', 'Sync failed: Server error');
  });

  it('should allow manual dismissal of toast notification', () => {
    cy.get(syncButtonSelector).click();

    cy.wait('@backgroundSync');

    cy.get(toastSelector).should('be.visible');

    cy.get(toastCloseSelector).should('be.visible').click();

    cy.get(toastSelector).should('not.exist');
  });

  it('should handle multiple sequential sync operations with separate toasts', () => {
    cy.get(syncButtonSelector).click();
    cy.wait('@backgroundSync');

    cy.get(toastSelector).should('be.visible');

    cy.get(syncButtonSelector).click();
    cy.wait('@backgroundSync');

    cy.get(toastSelector).should('have.length', 2);
  });

  it('should display toast with proper accessibility attributes', () => {
    cy.get(syncButtonSelector).click();

    cy.wait('@backgroundSync');

    cy.get(toastSelector)
      .should('have.attr', 'role', 'alert')
      .and('have.attr', 'aria-live', 'polite');

    cy.get(toastMessageSelector)
      .should('have.attr', 'id')
      .then((id) => {
        cy.get(toastSelector).should('have.attr', 'aria-describedby', id);
      });
  });

  it('should handle network timeout during sync gracefully', () => {
    cy.intercept('POST', '**/api/sync', (req) => {
      req.destroy();
    }).as('syncTimeout');

    cy.get(syncButtonSelector).click();

    cy.wait('@syncTimeout');

    cy.get(toastSelector)
      .should('be.visible')
      .and('have.class', 'toast-error');

    cy.get(toastMessageSelector)
      .should('contain.text', 'Network error');
  });

  it('should stack multiple toasts without overlapping', () => {
    cy.get(syncButtonSelector).click();
    cy.wait('@backgroundSync');

    cy.get(syncButtonSelector).click();
    cy.wait('@backgroundSync');

    cy.get(syncButtonSelector).click();
    cy.wait('@backgroundSync');

    cy.get(toastSelector).should('have.length', 3);

    cy.get(toastSelector).each(($toast, index) => {
      cy.wrap($toast)
        .should('be.visible')
        .invoke('css', 'position')
        .should('equal', 'fixed');
    });
  });
});
